module palindrome_cutter (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] char_in,\n    input wire [3:0] len,\n    output reg [3:0] k,\n    output reg [7:0] palindrome_mem [0:15][0:15],\n    output reg [3:0] palindrome_len [0:15],\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE      = 3'd0;\n    localparam [2:0] READ      = 3'd1;\n    localparam [2:0] COMPUTE_K = 3'd2;\n    localparam [2:0] BUILD     = 3'd3;\n    localparam [2:0] OUTPUT    = 3'd4;\n\n    reg [2:0] state;\n    reg [3:0] idx;\n    reg [3:0] ctr [0:3];\n    reg [3:0] odd_count;\n    reg [7:0] temp_palindrome [0:15];\n    reg [3:0] temp_idx;\n    reg [1:0] char_idx;\n    reg [3:0] pal_idx;\n    reg mirror_flag;\n\n    integer i, j;\n\n    // ASCII mapping functions\n    function [1:0] char_to_idx(input [7:0] c);\n        case(c)\n            8'h61: char_to_idx = 2'd0; // 'a'\n            8'h62: char_to_idx = 2'd1; // 'b'\n            8'h63: char_to_idx = 2'd2; // 'c'\n            8'h64: char_to_idx = 2'd3; // 'd'\n            default: char_to_idx = 2'd0;\n        endcase\n    endfunction\n\n    function [7:0] idx_to_char(input [1:0] i);\n        case(i)\n            0: idx_to_char = 8'h61;\n            1: idx_to_char = 8'h62;\n            2: idx_to_char = 8'h63;\n            3: idx_to_char = 8'h64;\n            default: idx_to_char = 8'h20;\n        endcase\n    endfunction\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            k <= 4'd0;\n            idx <= 4'd0;\n            pal_idx <= 4'd0;\n            temp_idx <= 4'd0;\n            odd_count <= 4'd0;\n            char_idx <= 2'd0;\n            mirror_flag <= 1'b0;\n            for (i = 0; i < 4; i = i + 1) ctr[i] <= 4'd0;\n            for (i = 0; i < 16; i = i + 1) begin\n                palindrome_len[i] <= 4'd0;\n                for (j = 0; j < 16; j = j + 1) begin\n                    palindrome_mem[i][j] <= 8'd0;\n                end\n            end\n            for (i = 0; i < 16; i = i + 1) temp_palindrome[i] <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    pal_idx <= 4'd0;\n                    temp_idx <= 4'd0;\n                    odd_count <= 4'd0;\n                    mirror_flag <= 1'b0;\n                    if (start) begin\n                        state <= READ;\n                        idx <= 4'd0;\n                        for (i = 0; i < 4; i = i + 1) ctr[i] <= 4'd0;\n                    end\n                end\n\n                READ: begin\n                    if (idx < len) begin\n                        char_idx <= char_to_idx(char_in);\n                        ctr[char_to_idx(char_in)] <= ctr[char_to_idx(char_in)] + 4'd1;\n                        idx <= idx + 4'd1;\n                    end else begin\n                        state <= COMPUTE_K;\n                        idx <= 4'd0;\n                    end\n                end\n\n                COMPUTE_K: begin\n                    odd_count <= 4'd0;\n                    for (i = 0; i < 4; i = i + 1) begin\n                        if (ctr[i][0] == 1'b1) odd_count <= odd_count + 4'd1;\n                    end\n                    if (odd_count <= 4'd1) k <= 4'd1;\n                    else k <= len;\n                    state <= BUILD;\n                    idx <= 4'd0;\n                    char_idx <= 2'd0;\n                end\n\n                BUILD: begin\n                    if (k == 4'd1) begin\n                        if (!mirror_flag) begin\n                            if (idx < 4) begin\n                                if (ctr[char_idx] > 4'd0) begin\n                                    if (ctr[char_idx][0] == 1'b0) begin\n                                        // Even count\n                                        for (j = 0; j < ctr[char_idx] / 2; j = j + 1) begin\n                                            if (temp_idx < 16) begin\n                                                temp_palindrome[temp_idx] <= idx_to_char(char_idx);\n                                                temp_idx <= temp_idx + 4'd1;\n                                            end\n                                        end\n                                    end else begin\n                                        // Odd count (place half-1)\n                                        for (j = 0; j < (ctr[char_idx] - 1) / 2; j = j + 1) begin\n                                            if (temp_idx < 16) begin\n                                                temp_palindrome[temp_idx] <= idx_to_char(char_idx);\n                                                temp_idx <= temp_idx + 4'd1;\n                                            end\n                                        end\n                                    end\n                                end\n                                char_idx <= char_idx + 2'd1;\n                                if (char_idx == 2'd3) idx <= idx + 4'd1;\n                            end else begin\n                                // Add center character\n                                mirror_flag <= 1'b1;\n                                idx <= 4'd0;\n                                temp_idx <= temp_idx;\n                                for (i = 0; i < 4; i = i + 1) begin\n                                    if (ctr[i][0] == 1'b1) begin\n                                        if (temp_idx < 16) begin\n                                            temp_palindrome[temp_idx] <= idx_to_char(i[1:0]);\n                                            temp_idx <= temp_idx + 4'd1;\n                                        end\n                                    end\n                                end\n                            end\n                        end else begin\n                            // Mirror the palindrome\n                            if (idx < temp_idx) begin\n                                palindrome_mem[0][pal_idx] <= temp_palindrome[idx];\n                                palindrome_mem[0][temp_idx * 2 - idx - 1] <= temp_palindrome[idx];\n                                pal_idx <= pal_idx + 4'd1;\n                                idx <= idx + 4'd1;\n                            end else begin\n                                palindrome_len[0] <= pal_idx;\n                                state <= OUTPUT;\n                            end\n                        end\n                    end else begin // k == len\n                        if (idx < len) begin\n                            palindrome_mem[idx][0] <= char_in;\n                            palindrome_len[idx] <= 4'd1;\n                            idx <= idx + 4'd1;\n                        end else begin\n                            state <= OUTPUT;\n                        end\n                    end\n                end\n\n                OUTPUT: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule